import { test, expect } from '@playwright/test';

test.describe('Table Row Expansion for Nested Details', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should expand a row to show nested details when user clicks expand button', async ({ page }) => {
    // Verify initial table state
    const tableRows = page.getByRole('rowgroup');
    await expect(tableRows).toHaveCount(3);

    // Verify first row is visible
    const firstRow = page.getByRole('row', { name: /Item 1/i });
    await expect(firstRow).toBeVisible();

    // Verify nested details are not visible initially
    const nestedDetails = page.getByRole('region', { name: /details/i });
    await expect(nestedDetails).not.toBeVisible();

    // Click expand button on first row
    const expandButton = page.getByRole('button', { name: /expand/i });
    await expandButton.click();

    // Verify nested details are now visible
    await expect(nestedDetails).toBeVisible();

    // Verify nested details contain expected content
    const nestedContent = page.getByText(/nested detail 1/i);
    await expect(nestedContent).toBeVisible();

    // Verify nested details are collapsible
    const collapseButton = page.getByRole('button', { name: /collapse/i });
    await expect(collapseButton).toBeVisible();

    // Click collapse button to hide nested details
    await collapseButton.click();

    // Verify nested details are hidden again
    await expect(nestedDetails).not.toBeVisible();

    // Verify row is still visible
    await expect(firstRow).toBeVisible();
  });

  test('should handle multiple row expansions and collapses', async ({ page }) => {
    // Verify initial table state
    const tableRows = page.getByRole('rowgroup');
    await expect(tableRows).toHaveCount(3);

    // Expand first row
    const firstRow = page.getByRole('row', { name: /Item 1/i });
    await firstRow.click();
    const nestedDetails = page.getByRole('region', { name: /details/i });
    await expect(nestedDetails).toBeVisible();

    // Expand second row
    const secondRow = page.getByRole('row', { name: /Item 2/i });
    await secondRow.click();
    const secondNestedDetails = page.getByRole('region', { name: /details/i });
    await expect(secondNestedDetails).toBeVisible();

    // Verify both rows have nested details visible
    await expect(nestedDetails).toBeVisible();
    await expect(secondNestedDetails).toBeVisible();

    // Verify nested details contain expected content
    const nestedContent1 = page.getByText(/nested detail 1/i);
    await expect(nestedContent1).toBeVisible();
    const nestedContent2 = page.getByText(/nested detail 2/i);
    await expect(nestedContent2).toBeVisible();

    // Collapse first row
    const collapseButton1 = page.getByRole('button', { name: /collapse/i });
    await collapseButton1.click();
    await expect(nestedDetails).not.toBeVisible();

    // Verify second row still has nested details visible
    await expect(secondNestedDetails).toBeVisible();

    // Collapse second row
    const collapseButton2 = page.getByRole('button', { name: /collapse/i });
    await collapseButton2.click();
    await expect(nestedDetails).not.toBeVisible();
    await expect(secondNestedDetails).not.toBeVisible();

    // Verify table rows are still visible
    await expect(tableRows).toHaveCount(3);
  });
});
